/* Flux: AP Physics C E&M Expedition — buildless GitHub Pages app */
const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const esc = value => String(value ?? "").replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const unitMeta = {
  0:{name:"Base camp",subtitle:"Mechanics, vectors & calculus",color:"#f59e0b"},
  8:{name:"Fields",subtitle:"Charge, field, flux & Gauss",color:"#2563eb"},
  9:{name:"Potential",subtitle:"Energy and electric potential",color:"#16a36a"},
  10:{name:"Conductors",subtitle:"Equilibrium and capacitors",color:"#16a36a"}
};
const state = {data:null,profile:null,route:"home",context:null,practice:{unit:"all",source:"all",id:null},exam:null,timer:null,lab:null};
const storageKey = "flux-em-profiles-v1";

function blankProfile(name){return {id:crypto.randomUUID?.() || Date.now().toString(36),name,created:Date.now(),lastSeen:Date.now(),lastStudy:null,streak:0,xp:0,completed:[],attempts:{},tags:{},notes:{},activity:[],settings:{reducedMotion:false}}}
function profiles(){try{return JSON.parse(localStorage.getItem(storageKey))||[]}catch{return []}}
function saveProfiles(list){localStorage.setItem(storageKey,JSON.stringify(list))}
function saveProfile(activity){if(!state.profile)return;if(activity){state.profile.activity.unshift({text:activity,at:Date.now()});state.profile.activity=state.profile.activity.slice(0,80)}updateStreak();state.profile.lastSeen=Date.now();const list=profiles(),i=list.findIndex(p=>p.id===state.profile.id);if(i>=0)list[i]=state.profile;else list.push(state.profile);saveProfiles(list);updateChrome();cloudSave();}
function updateStreak(){const today=new Date().toDateString();if(state.profile.lastStudy===today)return;const prev=new Date(Date.now()-86400000).toDateString();state.profile.streak=state.profile.lastStudy===prev?(state.profile.streak||0)+1:1;state.profile.lastStudy=today}
function selectProfile(id){state.profile=profiles().find(p=>p.id===id);if(!state.profile)return;state.profile.completed ||= [];state.profile.attempts ||= {};state.profile.tags ||= {};state.profile.activity ||= [];localStorage.setItem("flux-em-active",id);$("#profileGate").hidden=true;$("#app").hidden=false;updateChrome();route();}
function setupProfiles(){const list=profiles(),box=$("#profileList");box.innerHTML=list.map(p=>`<button class="existing-profile" data-profile="${esc(p.id)}"><span class="avatar">${esc(p.name[0].toUpperCase())}</span><span><b>${esc(p.name)}</b><small>${p.xp||0} XP · ${p.completed?.length||0} trails complete</small></span></button>`).join("");$$('[data-profile]',box).forEach(b=>b.onclick=()=>selectProfile(b.dataset.profile));$("#profileForm").onsubmit=e=>{e.preventDefault();const name=$("#newProfile").value.trim();if(!name)return;const p=blankProfile(name);const all=profiles();all.push(p);saveProfiles(all);selectProfile(p.id)};const active=localStorage.getItem("flux-em-active");if(active&&list.some(p=>p.id===active))selectProfile(active)}
function updateChrome(){if(!state.profile||!state.data)return;const total=state.data.lessons.length,done=state.profile.completed.filter(x=>x.startsWith("lesson:")).length,pct=Math.round(done/total*100);$("#profileName").textContent=state.profile.name;$("#profileInitial").textContent=state.profile.name[0].toUpperCase();$("#profileLevel").textContent=`Level ${Math.floor((state.profile.xp||0)/250)+1}`;$("#streakValue").textContent=`${state.profile.streak||0} day${state.profile.streak===1?"":"s"}`;$("#globalProgress").style.width=pct+"%";$("#globalPercent").textContent=pct+"%"}
function completed(key){return state.profile.completed.includes(key)}
function markComplete(key,xp=25,label="Trail completed"){if(!completed(key)){state.profile.completed.push(key);state.profile.xp=(state.profile.xp||0)+xp;saveProfile(label);toast(`+${xp} XP · saved`)}}
function toast(text){const el=$("#toast");el.textContent=text;el.classList.add("show");clearTimeout(el._t);el._t=setTimeout(()=>el.classList.remove("show"),2500)}
function route(){if(!state.profile||!state.data)return;const raw=location.hash.slice(1)||"home",[name,arg]=raw.split("/");state.route=name;state.context=null;$$('#mainNav a').forEach(a=>a.classList.toggle("active",a.dataset.route===name));const views={home:renderHome,map:renderMap,lesson:()=>renderLesson(arg),practice:renderPractice,worked:renderWorked,frq:renderFRQs,labs:renderLabs,lab:()=>renderLab(arg),exam:renderExam,cheatsheet:renderCheatsheet,settings:renderSettings,search:renderSearch};(views[name]||renderHome)();requestAnimationFrame(()=>window.scrollTo({top:0,left:0,behavior:"instant"}));$("#view").focus({preventScroll:true});}
function setCrumb(text){$("#crumb").textContent=text}
function pageHead(kicker,title,copy,action=""){return `<div class="page-head"><div><span class="kicker">${esc(kicker)}</span><h1>${esc(title)}</h1><p>${esc(copy)}</p></div>${action}</div>`}
function nextLesson(){return state.data.lessons.find(l=>!completed(`lesson:${l.id}`))||state.data.lessons[0]}
function lessonProgress(unit){const all=state.data.lessons.filter(l=>l.unit===unit),done=all.filter(l=>completed(`lesson:${l.id}`)).length;return {all:all.length,done,pct:all.length?Math.round(done/all.length*100):0}}

function renderHome(){setCrumb("Base camp");const next=nextLesson(),attempts=Object.values(state.profile.attempts),correct=attempts.filter(a=>a.correct).length;$("#view").innerHTML=`
  <section class="hero"><div class="hero-main"><span class="kicker">WELCOME BACK, ${esc(state.profile.name.toUpperCase())}</span><h1>Physics is a landscape.<br><em>Learn to read it.</em></h1><p>Begin with arrows and tiny sums, then travel through fields, energy, and capacitors. Every equation grows from a physical story.</p><div class="hero-actions"><a class="btn primary" href="#lesson/${next.id}">Continue: ${esc(next.title)}</a><a class="btn ghost" href="#map">Open map</a></div></div>
  <div class="hero-side"><div class="quest-card"><div class="ring" style="--p:${lessonProgress(next.unit).pct}%"><b>${lessonProgress(next.unit).pct}%</b></div><span class="kicker">NEXT TRAIL</span><h3>${esc(next.title)}</h3><p>${esc(next.goal)}</p><a class="btn cyan" href="#lesson/${next.id}">Enter trail →</a></div><div class="stats-row"><div class="stat-card"><b>${state.profile.xp||0}</b><small>XP earned</small></div><div class="stat-card"><b>${correct}</b><small>answers right</small></div><div class="stat-card"><b>${state.profile.streak||0}</b><small>day streak</small></div></div></div></section>
  <div class="section-title"><h2>Your three worlds</h2><a href="#map">View complete route →</a></div><div class="units-grid">${[8,9,10].map(u=>{const p=lessonProgress(u),m=unitMeta[u];return `<a class="unit-card" style="--unit:${m.color}" href="#map"><span class="unit-num">${u}</span><h3>${m.name}</h3><p>${m.subtitle}</p><div class="mini-track"><i style="width:${p.pct}%"></i></div><footer><span>${p.done}/${p.all} lessons</span><span>${p.pct}%</span></footer></a>`}).join("")}</div>
  <div class="section-title"><h2>Today’s instruments</h2></div><div class="labs-grid"><a class="lab-card" style="--lab:#2563eb" href="#lab/field"><span class="lab-icon">⌁</span><h2>Field sculptor</h2><p>Place charges and watch the vector field rebuild itself.</p></a><a class="lab-card" style="--lab:#16a36a" href="#lab/integral"><span class="lab-icon">∫</span><h2>Slice integrator</h2><p>Turn a continuous rod into a visible sum of little contributions.</p></a><a class="lab-card" style="--lab:#16a36a" href="#practice"><span class="lab-icon">◎</span><h2>Question vault</h2><p>All 295 uploaded MCQs with diagrams and worked explanations.</p></a></div>`}

function renderMap(){setCrumb("Expedition map");const groups=[0,8,9,10];$("#view").innerHTML=pageHead("YOUR ROUTE","The field expedition","Move in order from the tools at Base Camp to the capacitor forest. You may open any trail; completed trails glow.")+`<div class="map-shell"><div class="map-grid">${groups.map(u=>{const m=unitMeta[u],lessons=state.data.lessons.filter(l=>l.unit===u);return `<section class="map-column" style="--unit:${m.color}"><h2>${u?`Unit ${u} · `:""}${m.name}</h2>${lessons.map((l,i)=>`<a class="map-node ${completed(`lesson:${l.id}`)?"done":""}" href="#lesson/${l.id}"><span class="node-orb">${completed(`lesson:${l.id}`)?"✓":esc(l.id)}</span><span><b>${esc(l.title)}</b><small>${esc(l.subtitle)}</small></span></a>`).join("")}</section>`}).join("")}</div></div>`}
function autoFormula(text){const parts=String(text).split(/(?<=[.!?])\s+/);return parts.map(p=>(/[=∫Σ√ε₀λσρΦΔπ]|\b(?:sin|cos|ln|dq|dE|E\(|V\(|Qenc|Ceq)\b/.test(p)&&p.length<190)?`<div class="formula">${esc(p)}</div>`:`<p>${esc(p)}</p>`).join("")}
function renderLesson(id){const l=state.data.lessons.find(x=>x.id===id)||state.data.lessons[0],m=unitMeta[l.unit];state.context={type:"lesson",item:l};setCrumb(`${m.name} / ${l.id}`);$("#view").innerHTML=`<div class="lesson-layout"><article><header class="lesson-hero" style="border-top:3px solid ${m.color}"><span class="kicker">${esc(l.subtitle)}</span><h1>${esc(l.title)}</h1><p class="goal">By the end, you can: ${esc(l.goal)}</p></header>${l.sections.map((s,i)=>`<section class="lesson-section" id="section-${i}"><span class="kicker">IDEA ${i+1}</span><h2>${esc(s.title)}</h2>${autoFormula(s.body)}</section>`).join("")}<section class="example-card"><span class="kicker">WORKED PATH</span><h2>Follow the reasoning</h2><div class="example-steps">${l.example.map(x=>`<div><span>${esc(x)}</span></div>`).join("")}</div></section><section class="check-card"><span class="kicker">TRAIL CHECK</span><h2>${esc(l.check.q)}</h2><div class="check-options">${l.check.options.map((o,i)=>`<button data-check="${i}">${String.fromCharCode(65+i)}. ${esc(o)}</button>`).join("")}</div><div class="feedback">${esc(l.check.why)}</div></section><div class="lesson-finish"><p>${completed(`lesson:${l.id}`)?"This trail is complete. Revisit it whenever the idea gets foggy.":"Mark the trail complete when you can explain the check in your own words."}</p><button id="finishLesson" class="btn ${completed(`lesson:${l.id}`)?"ghost":"primary"}">${completed(`lesson:${l.id}`)?"✓ Completed":"Complete trail"}</button></div></article><aside class="lesson-toc"><b>On this trail</b>${l.sections.map((s,i)=>`<button data-scroll="section-${i}">${esc(s.title)}</button>`).join("")}<a href="#practice" style="color:var(--cyan)">Practice questions →</a></aside></div>`;$$('[data-scroll]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.scroll).scrollIntoView({behavior:"smooth",block:"start"}));$$('[data-check]').forEach(b=>b.onclick=()=>{const choice=+b.dataset.check;$$('[data-check]').forEach((x,i)=>{x.disabled=true;if(i===l.check.answer)x.classList.add("correct");else if(i===choice)x.classList.add("wrong")});$(".feedback").classList.add("show");if(choice===l.check.answer){state.profile.xp=(state.profile.xp||0)+5;saveProfile(`Checked ${l.id}`)}});$("#finishLesson").onclick=()=>{markComplete(`lesson:${l.id}`,30,`Completed ${l.title}`);renderLesson(l.id)}}

function sourceFor(id){return state.data.sources.find(s=>s.id===id)}
function questionPage(q){const src=sourceFor(q.source);if(!src)return null;const hit=src.questions.find(x=>x.number===q.number);return hit?.page||1}
function questionSourceText(q){const src=sourceFor(q.source),page=questionPage(q);return src?.pages.find(p=>p.page===page)?.text||"Source text unavailable."}
function choiceLetters(q){const src=sourceFor(q.source),page=questionPage(q),text=src?.pages.find(p=>p.page===page)?.text||"";const start=text.search(new RegExp(`(?:^|\\n)${q.number}\\.\\s*(?:\\n|$)`)),tail=start>=0?text.slice(start):text;const next=tail.slice(3).search(/\n\d+\.\s*(?:\n|$)/),segment=next>=0?tail.slice(0,next+3):tail,letters=[...segment.matchAll(/\(([A-E])\)/g)].map(m=>m[1]);const unique=[...new Set(letters)];return unique.length>=3?unique:["A","B","C","D",...(q.answer==="E"?["E"]:[])]}
function renderPractice(){setCrumb("Question vault");const units=["all","8","9","10"],all=state.data.solutions;let filtered=all.filter(q=>state.practice.unit==="all"||q.source.startsWith(state.practice.unit+"."));const sources=["all",...new Set(all.filter(q=>state.practice.unit==="all"||q.source.startsWith(state.practice.unit+".")).map(q=>q.source))];if(state.practice.source!=="all"&&!sources.includes(state.practice.source))state.practice.source="all";filtered=filtered.filter(q=>state.practice.source==="all"||q.source===state.practice.source);if(!state.practice.id||!filtered.some(q=>q.id===state.practice.id))state.practice.id=filtered[0]?.id;const q=filtered.find(x=>x.id===state.practice.id);$("#view").innerHTML=pageHead("295 UPLOADED MCQs","Question vault","Every question stays paired with its original page, answer, reasoning, common trap, and integration connection.",`<button class="btn ghost" id="reviewDifficult">Review difficult</button>`)+`<div class="filterbar" id="unitFilters">${units.map(u=>`<button data-unit="${u}" class="${state.practice.unit===u?"active":""}">${u==="all"?"All units":`Unit ${u}`}</button>`).join("")}</div><div class="filterbar" id="sourceFilters">${sources.map(s=>`<button data-source="${s}" class="${state.practice.source===s?"active":""}">${s==="all"?"All topics":s}</button>`).join("")}</div><div class="practice-layout"><div class="question-list">${filtered.map(item=>{const a=state.profile.attempts[item.id];return `<div class="question-card ${item.id===q?.id?"active":""}" data-qid="${item.id}"><span class="qnum">${item.number}</span><span><b>Topic ${item.source}</b><small>${esc(item.title)}</small></span><i class="status-dot ${a?(a.correct?"correct":"wrong"):""}"></i></div>`}).join("")}</div><div class="question-workspace">${q?questionWorkspace(q):"<p>No questions match this filter.</p>"}</div></div>`;$$('[data-unit]').forEach(b=>b.onclick=()=>{state.practice.unit=b.dataset.unit;state.practice.source="all";renderPractice()});$$('[data-source]').forEach(b=>b.onclick=()=>{state.practice.source=b.dataset.source;renderPractice()});$$('[data-qid]').forEach(b=>b.onclick=()=>{state.practice.id=b.dataset.qid;renderPractice()});$("#reviewDifficult").onclick=()=>{const hard=filtered.filter(x=>state.profile.tags[x.id]?.includes("difficult"));if(hard.length){state.practice.id=hard[0].id;toast(`${hard.length} difficult questions in this view`);renderPractice()}else toast("No difficult tags in this view yet")};wireQuestion(q)}
function questionWorkspace(q){state.context={type:"question",item:q};const src=sourceFor(q.source),page=questionPage(q),image=src?.pages.find(p=>p.page===page)?.image,attempt=state.profile.attempts[q.id],tags=state.profile.tags[q.id]||[];return `<div class="source-note"><span>${esc(q.source)} · question ${q.number} · source page ${page}</span><span>GitHub-ready optimized copy</span></div><div class="source-frame">${image?`<img src="${esc(image)}" alt="Source page containing question ${q.number}" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><pre hidden>${esc(questionSourceText(q))}</pre>`:`<pre>${esc(questionSourceText(q))}</pre>`}</div><details class="coach-step"><summary>Accessible source text</summary><pre style="white-space:pre-wrap">${esc(questionSourceText(q))}</pre></details><section class="mcq-panel"><span class="kicker">SELECT YOUR ANSWER</span><h2>${esc(q.title)}</h2><div class="mcq-options">${choiceLetters(q).map(c=>`<button data-answer="${c}" class="${attempt?(c===q.answer?"correct":c===attempt.choice&&!attempt.correct?"wrong":""):""}" ${attempt?"disabled":""}>${c}</button>`).join("")}</div>${attempt?solutionHTML(q):`<div id="solutionSlot"><button id="revealSolution" class="btn ghost" style="margin-top:14px">Show worked solution</button></div>`}<div class="question-tools"><button class="tag ${tags.includes("difficult")?"active":""}" data-tag="difficult">⚑ Difficult</button><button class="tag ${tags.includes("review")?"active":""}" data-tag="review">↻ Review later</button><button class="tag ${tags.includes("mastered")?"active":""}" data-tag="mastered">✓ Mastered</button><button class="tag" id="askThis">✦ Ask tutor</button></div></section>`}
function solutionHTML(q){return `<div class="solution"><span class="kicker">WORKED EXPLANATION · ANSWER ${q.answer}</span>${q.steps.map((s,i)=>`<div class="solution-step"><i>${i+1}</i><span>${esc(s)}</span></div>`).join("")}<div class="callout pitfall"><b>Common trap:</b> ${esc(q.pitfall)}</div><div class="callout integral"><b>Integration lens:</b> ${esc(q.integration)}</div></div>`}
function wireQuestion(q){if(!q)return;$$('[data-answer]').forEach(b=>b.onclick=()=>{const choice=b.dataset.answer,correct=choice===q.answer;state.profile.attempts[q.id]={choice,correct,at:Date.now()};state.profile.xp=(state.profile.xp||0)+(correct?8:2);saveProfile(`${correct?"Solved":"Attempted"} ${q.id}`);toast(correct?"Correct · +8 XP":"Saved · study the reasoning");renderPractice()});const reveal=$("#revealSolution");if(reveal)reveal.onclick=()=>{$("#solutionSlot").innerHTML=solutionHTML(q)};$$('[data-tag]').forEach(b=>b.onclick=()=>toggleTag(q.id,b.dataset.tag));const ask=$("#askThis");if(ask)ask.onclick=openTutor}
function toggleTag(id,tag){const tags=state.profile.tags[id]||[],i=tags.indexOf(tag);if(i>=0)tags.splice(i,1);else tags.push(tag);state.profile.tags[id]=tags;saveProfile(`Tagged ${id}: ${tag}`);renderPractice()}

function renderWorked(){setCrumb("Worked examples");const unit=new URLSearchParams(location.hash.split("?")[1]||"").get("unit")||"all",items=state.data.lecture.filter(x=>unit==="all"||String(x.unit)===unit);$("#view").innerHTML=pageHead("25 LECTURE EXAMPLES","Worked-example observatory","These reconstruct every actual example in the supplied 86-page class deck, including its integration route and source-page corrections.")+`<div class="filterbar">${["all",8,9].map(u=>`<a class="${String(unit)===String(u)?"active":""}" href="#worked${u==="all"?"":`?unit=${u}`}">${u==="all"?"All examples":`Unit ${u}`}</a>`).join("")}</div><div class="frq-grid">${items.map(x=>`<article class="frq-card"><span class="kicker">SOURCE PAGE ${x.page} · UNIT ${x.unit}</span><h2>${esc(x.title)}</h2><p>${esc(x.prompt)}</p><div class="step-coach">${x.steps.map((s,i)=>`<details class="coach-step"><summary>Step ${i+1}</summary><p class="answer">${esc(s)}</p></details>`).join("")}</div><div class="frq-final">${esc(x.answer)}</div><div class="callout integral"><b>Integration lens:</b> ${esc(x.integration)}</div></article>`).join("")}</div>`}

function renderFRQs(){setCrumb("FRQ workshop");const filter=location.hash.split("?")[1],items=state.data.frqs.filter(x=>!filter||String(x.unit)===filter);$("#view").innerHTML=pageHead("12 GUIDED DERIVATIONS","FRQ workshop","Six supplied free-response problems and six new transfer problems. Open one hint at a time; every step states what earns credit.")+`<div class="filterbar">${["all",8,9,10].map(u=>`<a href="${u==="all"?"#frq":`#frq?${u}`}" class="${(!filter&&u==="all")||filter==u?"active":""}">Unit ${u==="all"?"all":u}</a>`).join("")}</div><div class="frq-grid">${items.map(f=>`<article class="frq-card"><span class="kicker">UNIT ${f.unit} · ${f.source==="original"?"TRANSFER PROBLEM":"SUPPLIED"}</span><h2>${esc(f.title)}</h2><p>${esc(f.prompt)}</p><div class="step-coach">${f.steps.map((s,i)=>`<details class="coach-step"><summary>Step ${i+1}: ${esc(s.question)}</summary><p class="hint"><b>Hint:</b> ${esc(s.hint)}</p><p class="answer">${esc(s.answer)}</p><p class="rubric">✓ ${esc(s.rubric)}</p></details>`).join("")}</div><details class="coach-step"><summary>Final result and checks</summary><p class="frq-final">${esc(f.final)}</p><p><b>Shortcut:</b> ${esc(f.shortcut)}</p><p><b>Common trap:</b> ${esc(f.pitfall)}</p></details><button class="btn ghost complete-frq" data-frq="${esc(f.id)}">${completed(`frq:${f.id}`)?"✓ Completed":"Mark complete"}</button></article>`).join("")}</div>`;$$('.complete-frq').forEach(b=>b.onclick=()=>{markComplete(`frq:${b.dataset.frq}`,40,`Completed ${b.dataset.frq}`);renderFRQs()})}

const labs=[{id:"field",title:"Field sculptor",icon:"⌁",desc:"Click to place positive or negative charges. Read the field vectors and equipotential colors."},{id:"integral",title:"Slice integrator",icon:"∫",desc:"Increase the number of rod slices and watch a discrete sum approach the exact integral."},{id:"flux",title:"Flux gate",icon:"□",desc:"Rotate a surface in a uniform field and see the dot product become visible."},{id:"induction",title:"Induction sequencer",icon:"↔",desc:"Put the four induction actions in physical order and watch electrons move."},{id:"potential",title:"Energy surfer",icon:"≈",desc:"Release a charged particle on a potential landscape and follow K + U."},{id:"capacitor",title:"Capacitor workshop",icon:"▥",desc:"Change area, gap, voltage, and dielectric; compare fixed-Q and fixed-V behavior."}];
function renderLabs(){setCrumb("Field labs");$("#view").innerHTML=pageHead("INTERACTIVE SANDBOXES","Field labs","Touch the model, change one thing, and explain what must happen before reading the numbers.")+`<div class="labs-grid">${labs.map((l,i)=>`<a class="lab-card" style="--lab:${["#2563eb","#16a36a","#f59e0b","#ff7a90","#6da8ff","#16a36a"][i]}" href="#lab/${l.id}"><span class="lab-icon">${l.icon}</span><h2>${l.title}</h2><p>${l.desc}</p><span class="kicker">OPEN LAB →</span></a>`).join("")}</div>`}
function renderLab(id){const lab=labs.find(x=>x.id===id)||labs[0];setCrumb(`Field labs / ${lab.title}`);$("#view").innerHTML=pageHead("LIVE MODEL",lab.title,lab.desc,`<a class="btn ghost" href="#labs">← All labs</a>`)+`<div class="lab-workbench"><div class="canvas-shell"><canvas id="labCanvas" width="900" height="560"></canvas><div class="lab-instruction" id="labInstruction"></div></div><aside class="lab-controls" id="labControls"></aside></div>`;state.lab={id,raf:null};initLab(id)}
function initLab(id){if(id==="field")fieldLab();else if(id==="integral")integralLab();else if(id==="flux")fluxLab();else if(id==="induction")inductionLab();else if(id==="potential")potentialLab();else capacitorLab()}
function canvasCtx(){const c=$("#labCanvas"),ctx=c.getContext("2d");return {c,ctx,w:c.width,h:c.height}}
function clearCanvas(ctx,w,h){ctx.clearRect(0,0,w,h);const g=ctx.createRadialGradient(w/2,h/2,30,w/2,h/2,w*.7);g.addColorStop(0,"#ffffff");g.addColorStop(1,"#e8f5ef");ctx.fillStyle=g;ctx.fillRect(0,0,w,h)}
function arrow(ctx,x,y,dx,dy,color="#2672c9"){const mag=Math.hypot(dx,dy)||1,scale=Math.min(18,2+Math.log10(mag+1)*5),ux=dx/mag,uy=dy/mag;ctx.strokeStyle=color;ctx.fillStyle=color;ctx.globalAlpha=.62;ctx.beginPath();ctx.moveTo(x-ux*scale/2,y-uy*scale/2);ctx.lineTo(x+ux*scale/2,y+uy*scale/2);ctx.stroke();ctx.beginPath();ctx.moveTo(x+ux*scale/2,y+uy*scale/2);ctx.lineTo(x+ux*scale/2-ux*5-uy*3,y+uy*scale/2-uy*5+ux*3);ctx.lineTo(x+ux*scale/2-ux*5+uy*3,y+uy*scale/2-uy*5-ux*3);ctx.fill();ctx.globalAlpha=1}
function fieldLab(){const {c,ctx,w,h}=canvasCtx(),charges=[{x:300,y:280,q:1},{x:600,y:280,q:-1}];let sign=1;$("#labControls").innerHTML=`<span class="kicker">SOURCE CHARGES</span><h2>Build a field</h2><p>Click the canvas to add the selected charge. Right-click a charge to remove it.</p><div class="filterbar"><button id="positive" class="active">+ Positive</button><button id="negative">− Negative</button></div><button class="btn ghost" id="resetLab">Reset dipole</button><div class="lab-readout" id="readout">Two source charges</div><p class="micro">Arrows show E, the force direction on a positive test charge. Background color loosely shows potential.</p>`;$("#positive").onclick=()=>{sign=1;$("#positive").classList.add("active");$("#negative").classList.remove("active")};$("#negative").onclick=()=>{sign=-1;$("#negative").classList.add("active");$("#positive").classList.remove("active")};$("#resetLab").onclick=()=>{charges.splice(0,99,{x:300,y:280,q:1},{x:600,y:280,q:-1});draw()};c.onclick=e=>{const r=c.getBoundingClientRect();charges.push({x:(e.clientX-r.left)*w/r.width,y:(e.clientY-r.top)*h/r.height,q:sign});draw()};c.oncontextmenu=e=>{e.preventDefault();const r=c.getBoundingClientRect(),x=(e.clientX-r.left)*w/r.width,y=(e.clientY-r.top)*h/r.height,i=charges.findIndex(q=>Math.hypot(q.x-x,q.y-y)<30);if(i>=0)charges.splice(i,1);draw()};$("#labInstruction").textContent="Click to add · right-click to remove";function draw(){clearCanvas(ctx,w,h);for(let y=35;y<h;y+=35)for(let x=35;x<w;x+=35){let ex=0,ey=0;for(const q of charges){const dx=x-q.x,dy=y-q.y,r2=dx*dx+dy*dy+140;ex+=q.q*dx/Math.pow(r2,1.5)*100000;ey+=q.q*dy/Math.pow(r2,1.5)*100000}arrow(ctx,x,y,ex,ey)}for(const q of charges){const g=ctx.createRadialGradient(q.x,q.y,2,q.x,q.y,35);g.addColorStop(0,q.q>0?"#fff":"#d9d4ff");g.addColorStop(1,q.q>0?"#ff6f85":"#498cff");ctx.fillStyle=g;ctx.beginPath();ctx.arc(q.x,q.y,18,0,Math.PI*2);ctx.fill();ctx.fillStyle="#03121e";ctx.font="bold 18px sans-serif";ctx.textAlign="center";ctx.fillText(q.q>0?"+":"−",q.x,q.y+6)}$("#readout").textContent=`${charges.length} source charge${charges.length===1?"":"s"} · net sign ${charges.reduce((s,q)=>s+q.q,0)}`};draw()}
function integralLab(){const {ctx,w,h}=canvasCtx();$("#labControls").innerHTML=`<span class="kicker">RIEMANN SUM</span><h2>How a field becomes an integral</h2><div class="control"><label><span>Slices N</span><b id="nVal">8</b></label><input id="n" type="range" min="1" max="80" value="8"></div><div class="control"><label><span>Observation distance d</span><b id="dVal">1.00 m</b></label><input id="d" type="range" min="30" max="250" value="100"></div><div class="lab-readout" id="readout"></div><p class="micro">Rod: L = 4 m, λ = 1 nC/m. This view uses the exact vector contribution from each finite slice.</p>`;$("#labInstruction").textContent="More slices → a smoother sum → the integral";function draw(){const N=+$("#n").value,d=+$("#d").value/100,L=4,lambda=1e-9,k=8.99e9,rodX=240,top=80,bottom=480,scale=(bottom-top)/L,obsX=rodX+d*scale,obsY=(top+bottom)/2;clearCanvas(ctx,w,h);ctx.strokeStyle="#2563eb";ctx.lineWidth=7;ctx.beginPath();ctx.moveTo(rodX,top);ctx.lineTo(rodX,bottom);ctx.stroke();let ex=0,dy=L/N;for(let i=0;i<N;i++){const yPhys=-L/2+(i+.5)*dy,y=obsY-yPhys*scale,r=Math.hypot(d,yPhys),dEi=k*lambda*dy/(r*r),dex=dEi*d/r,dey=-dEi*yPhys/r;ex+=dex;ctx.fillStyle=`rgba(167,139,250,${Math.min(.9,.15+N<15?.5:.2)})`;ctx.fillRect(rodX-8,y-dy*scale/2+1,16,Math.max(2,dy*scale-2));ctx.strokeStyle="rgba(167,139,250,.35)";ctx.beginPath();ctx.moveTo(rodX,y);ctx.lineTo(obsX,obsY);ctx.stroke();arrow(ctx,obsX,obsY,dex*1e4,dey*1e4,"#16a36a")}const exact=2*k*lambda*(L/2)/(d*Math.sqrt(d*d+(L/2)**2));ctx.fillStyle="#f59e0b";ctx.beginPath();ctx.arc(obsX,obsY,11,0,Math.PI*2);ctx.fill();ctx.fillStyle="#15324a";ctx.font="16px sans-serif";ctx.fillText("observation point",obsX+20,obsY-18);$("#nVal").textContent=N;$("#dVal").textContent=d.toFixed(2)+" m";$("#readout").innerHTML=`Σ dEₓ = ${ex.toFixed(2)} N/C<br>Exact integral = ${exact.toFixed(2)} N/C<br>Error = ${Math.abs(ex-exact)/exact*100<.01?"<0.01":(Math.abs(ex-exact)/exact*100).toFixed(2)}%`};$("#n").oninput=draw;$("#d").oninput=draw;draw()}
function fluxLab(){const {ctx,w,h}=canvasCtx();$("#labControls").innerHTML=`<span class="kicker">DOT PRODUCT</span><h2>Rotate the area vector</h2><div class="control"><label><span>Angle θ to field</span><b id="thetaVal">30°</b></label><input id="theta" type="range" min="0" max="180" value="30"></div><div class="control"><label><span>Field E</span><b id="eVal">5 N/C</b></label><input id="ef" type="range" min="1" max="12" value="5"></div><div class="lab-readout" id="readout"></div><p class="micro">Area A = 2 m². The angle is measured from E to the surface normal—not to the surface.</p>`;$("#labInstruction").textContent="Flux is signed: outward vs inward matters";function draw(){const th=+$("#theta").value*Math.PI/180,E=+$("#ef").value,A=2,cx=w/2,cy=h/2;clearCanvas(ctx,w,h);ctx.strokeStyle="rgba(94,231,247,.32)";for(let y=100;y<h;y+=55){for(let x=50;x<w-80;x+=120)arrow(ctx,x,y,40,0,"#2563eb")};ctx.save();ctx.translate(cx,cy);ctx.rotate(th);ctx.fillStyle="rgba(167,139,250,.34)";ctx.strokeStyle="#16a36a";ctx.lineWidth=4;ctx.fillRect(-8,-140,16,280);ctx.strokeRect(-8,-140,16,280);ctx.strokeStyle="#f59e0b";ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(150,0);ctx.stroke();arrow(ctx,140,0,30,0,"#f59e0b");ctx.restore();ctx.fillStyle="#f59e0b";ctx.font="16px sans-serif";ctx.fillText("A normal",cx+Math.cos(th)*150,cy+Math.sin(th)*150);const flux=E*A*Math.cos(th);$("#thetaVal").textContent=Math.round(th*180/Math.PI)+"°";$("#eVal").textContent=E+" N/C";$("#readout").textContent=`Φ = EA cos θ = ${flux.toFixed(2)} N·m²/C`};$("#theta").oninput=draw;$("#ef").oninput=draw;draw()}
function inductionLab(){const {ctx,w,h}=canvasCtx();const correct=["near","ground","disconnect","remove"],chosen=[];$("#labControls").innerHTML=`<span class="kicker">SEQUENCE GAME</span><h2>Leave the sphere negative</h2><p>Choose actions in order using a positive rod.</p><div class="filterbar" id="actions"><button data-act="ground">Connect ground</button><button data-act="remove">Remove rod</button><button data-act="near">Bring + rod near</button><button data-act="disconnect">Disconnect ground</button></div><div class="lab-readout" id="readout">Choose the first action.</div><button class="btn ghost" id="resetLab">Reset</button><p class="micro">The rod never touches. Watch the electron count and whether Earth remains connected.</p>`;$("#labInstruction").textContent="A sequence changes what charge is free to return";function draw(){clearCanvas(ctx,w,h);const near=chosen.includes("near")&&!chosen.includes("remove"),ground=chosen.includes("ground")&&!chosen.includes("disconnect"),trapped=chosen.includes("disconnect");ctx.strokeStyle="#6b879a";ctx.lineWidth=4;ctx.beginPath();ctx.arc(480,270,105,0,Math.PI*2);ctx.stroke();ctx.fillStyle="rgba(180,210,225,.08)";ctx.fill();if(near){ctx.fillStyle="#ff7187";ctx.fillRect(160,210,70,120);ctx.fillStyle="white";ctx.font="bold 30px sans-serif";ctx.fillText("+ +",165,280)}const electronCount=ground&&near?11:trapped?11:8;for(let i=0;i<electronCount;i++){const angle=2*Math.PI*i/electronCount,shift=near?35:0,x=480+Math.cos(angle)*75-shift,y=270+Math.sin(angle)*75;ctx.fillStyle="#4f91ff";ctx.beginPath();ctx.arc(x,y,8,0,Math.PI*2);ctx.fill();ctx.fillStyle="white";ctx.font="12px sans-serif";ctx.fillText("−",x-4,y+4)}if(ground){ctx.strokeStyle="#16a36a";ctx.beginPath();ctx.moveTo(480,375);ctx.lineTo(480,470);ctx.stroke();ctx.fillStyle="#16a36a";ctx.fillText("EARTH",452,500)}ctx.fillStyle="#15324a";ctx.font="16px sans-serif";ctx.fillText(ground?"Electrons may exchange with Earth":trapped?"Excess electrons are trapped":"Net charge can redistribute",345,70)}function choose(a){const expected=correct[chosen.length];if(a!==expected){$("#readout").textContent=`Not yet. Ask: must the rod be present before charge flows?`;toast("Sequence paused — try another action");return}chosen.push(a);$$('[data-act]').forEach(b=>{if(b.dataset.act===a)b.disabled=true});$("#readout").textContent=chosen.length===4?"Success: the sphere is negative.":`Good. ${chosen.length}/4 actions correct.`;draw();if(chosen.length===4)markComplete("lab:induction",20,"Completed induction game")};$$('[data-act]').forEach(b=>b.onclick=()=>choose(b.dataset.act));$("#resetLab").onclick=()=>{chosen.length=0;$$('[data-act]').forEach(b=>b.disabled=false);$("#readout").textContent="Choose the first action.";draw()};draw()}
function potentialLab(){const {ctx,w,h}=canvasCtx();let running=false,x=120,v=0,last=0;$("#labControls").innerHTML=`<span class="kicker">ENERGY CONSERVATION</span><h2>Release a charge</h2><div class="control"><label><span>Charge q</span><b id="qVal">+1 C</b></label><input id="q" type="range" min="-2" max="2" step="1" value="1"></div><div class="control"><label><span>Landscape height V₀</span><b id="vVal">6 V</b></label><input id="v0" type="range" min="1" max="10" value="6"></div><button class="btn primary" id="release">Release</button> <button class="btn ghost" id="resetLab">Reset</button><div class="lab-readout" id="readout"></div><p class="micro">Model mass m = 1 kg. The motion follows F = −q dV/dx and preserves K + qV.</p>`;$("#labInstruction").textContent="Positive charge rolls toward lower potential; negative charge reverses the landscape";function V(px){const V0=+$("#v0").value;return V0*(.5+.32*Math.sin(px/w*Math.PI*2)+.13*Math.sin(px/w*Math.PI*5))}function dV(px){const V0=+$("#v0").value;return V0*(.32*Math.cos(px/w*Math.PI*2)*2*Math.PI/w+.13*Math.cos(px/w*Math.PI*5)*5*Math.PI/w)}let total=0;function reset(){running=false;x=120;v=0;total=(+$("#q").value)*V(x);draw()}function draw(){clearCanvas(ctx,w,h);ctx.strokeStyle="#16a36a";ctx.lineWidth=4;ctx.beginPath();for(let px=0;px<=w;px+=4){const y=h-100-V(px)*35;if(px===0)ctx.moveTo(px,y);else ctx.lineTo(px,y)}ctx.stroke();const y=h-100-V(x)*35;ctx.fillStyle=(+$("#q").value)>0?"#ff7a90":"#5e9cff";ctx.beginPath();ctx.arc(x,y-15,14,0,Math.PI*2);ctx.fill();const U=(+$("#q").value)*V(x),K=.5*v*v;$("#qVal").textContent=(+$("#q").value>=0?"+":"")+$("#q").value+" C";$("#vVal").textContent=$("#v0").value+" V";$("#readout").innerHTML=`V = ${V(x).toFixed(2)} V<br>U = ${U.toFixed(2)} J · K = ${K.toFixed(2)} J<br>K + U = ${(K+U).toFixed(2)} J`}function frame(t){if(!running)return;const dt=Math.min(.025,(t-last)/1000||.016);last=t;const q=+$("#q").value;v+=(-q*dV(x))*dt*500;x+=v*dt*25;if(x<15||x>w-15){v*=-1;x=Math.max(15,Math.min(w-15,x))}draw();state.lab.raf=requestAnimationFrame(frame)}$("#release").onclick=()=>{if(!running){running=true;last=0;state.lab.raf=requestAnimationFrame(frame)}};$("#resetLab").onclick=reset;$("#q").oninput=reset;$("#v0").oninput=reset;reset()}
function capacitorLab(){const {ctx,w,h}=canvasCtx();$("#labControls").innerHTML=`<span class="kicker">PARALLEL PLATES</span><h2>Change the geometry</h2><div class="control"><label><span>Plate area A</span><b id="aVal">2.0 m²</b></label><input id="area" type="range" min="5" max="40" value="20"></div><div class="control"><label><span>Gap d</span><b id="dVal">2.0 cm</b></label><input id="gap" type="range" min="5" max="60" value="20"></div><div class="control"><label><span>Voltage V</span><b id="vVal">12 V</b></label><input id="voltage" type="range" min="1" max="30" value="12"></div><div class="control"><label><span>Dielectric κ</span><b id="kVal">1</b></label><input id="kappa" type="range" min="1" max="8" value="1"></div><div class="lab-readout" id="readout"></div><p class="micro">Battery-connected mode: V is fixed while Q adjusts. C = κε₀A/d.</p>`;$("#labInstruction").textContent="Predict the trend before moving each slider";function draw(){const A=+$("#area").value/10,d=+$("#gap").value/1000,V=+$("#voltage").value,k=+$("#kappa").value,eps=8.854e-12,C=k*eps*A/d,Q=C*V,U=.5*C*V*V,cx=w/2,gap=Math.min(260,60+d*2400),ph=120+A*45;clearCanvas(ctx,w,h);ctx.fillStyle="#89a5b9";ctx.fillRect(cx-gap/2-18,h/2-ph/2,18,ph);ctx.fillRect(cx+gap/2,h/2-ph/2,18,ph);if(k>1){ctx.fillStyle=`rgba(167,139,250,${.08+k*.035})`;ctx.fillRect(cx-gap/2,h/2-ph/2,gap,ph)}ctx.fillStyle="#ff8a9b";ctx.font="bold 24px sans-serif";for(let y=h/2-ph/2+22;y<h/2+ph/2;y+=34)ctx.fillText("+",cx-gap/2-16,y);ctx.fillStyle="#6ea7ff";for(let y=h/2-ph/2+22;y<h/2+ph/2;y+=34)ctx.fillText("−",cx+gap/2-14,y);ctx.strokeStyle="#2563eb";for(let y=h/2-ph/2+22;y<h/2+ph/2;y+=28){ctx.beginPath();ctx.moveTo(cx-gap/2,y);ctx.lineTo(cx+gap/2,y);ctx.stroke()}$("#aVal").textContent=A.toFixed(1)+" m²";$("#dVal").textContent=(d*100).toFixed(1)+" cm";$("#vVal").textContent=V+" V";$("#kVal").textContent=k;$("#readout").innerHTML=`C = ${(C*1e9).toFixed(2)} nF<br>Q = ${(Q*1e9).toFixed(2)} nC<br>E = ${(V/d).toFixed(0)} V/m<br>U = ${(U*1e9).toFixed(2)} nJ`}$$('#labControls input').forEach(x=>x.oninput=draw);draw()}

function renderExam(){setCrumb("Mock exams");if(state.exam)return renderExamStage();$("#view").innerHTML=pageHead("TIMED & UNTAMED","Mock exams","Fresh question sets are drawn from your uploaded bank. Answers and explanations stay hidden until submission.")+`<div class="exam-setup"><article class="exam-card"><span class="kicker">QUICK TREK</span><h2>20 MCQs · 35 minutes</h2><p>Mixed Units 8–10. A focused check for one study block.</p><button class="btn primary" data-exam="20,35,all">Begin</button></article><article class="exam-card"><span class="kicker">MIDTERM</span><h2>35 MCQs + 2 FRQs</h2><p>70-minute cumulative midterm with one integration-first FRQ.</p><button class="btn primary" data-exam="35,70,all">Begin</button></article><article class="exam-card"><span class="kicker">UNIT RUN</span><h2>20 MCQs · one unit</h2><p>Choose Unit 8, 9, or 10 in the next step.</p><div class="filterbar">${[8,9,10].map(u=>`<button data-exam="20,35,${u}">Unit ${u}</button>`).join("")}</div></article></div><div class="section-title"><h2>Practice strategy</h2></div><div class="cheat-grid"><div class="cheat-card"><h3>First pass</h3><p>Answer immediate conceptual questions. Flag long algebra. Do not let one diagram consume the clock.</p></div><div class="cheat-card"><h3>Second pass</h3><p>Draw directions before signs. Check units and limiting cases before selecting an answer.</p></div><div class="cheat-card"><h3>After submission</h3><p>Tag the underlying concept, then redo without looking at the explanation.</p></div></div>`;$$('[data-exam]').forEach(b=>b.onclick=()=>startExam(...b.dataset.exam.split(",")))}
function startExam(count,minutes,unit){let pool=state.data.solutions.filter(q=>unit==="all"||q.source.startsWith(unit+"."));pool=[...pool].sort(()=>Math.random()-.5).slice(0,+count);state.exam={items:pool,answers:{},index:0,end:Date.now()+minutes*60000,minutes:+minutes,unit,submitted:false};renderExamStage();clearInterval(state.timer);state.timer=setInterval(()=>{const t=$("#examTimer");if(t)t.textContent=timeLeft();if(Date.now()>=state.exam.end)submitExam()},1000)}
function timeLeft(){const ms=Math.max(0,state.exam.end-Date.now()),m=Math.floor(ms/60000),s=Math.floor(ms%60000/1000);return `${m}:${String(s).padStart(2,"0")}`}
function renderExamStage(){const ex=state.exam;if(ex.submitted)return renderExamResults();const q=ex.items[ex.index],src=sourceFor(q.source),page=questionPage(q),image=src?.pages.find(p=>p.page===page)?.image;$("#view").innerHTML=`<div class="exam-stage"><div class="exam-top"><span>Question ${ex.index+1} of ${ex.items.length}</span><b class="timer" id="examTimer">${timeLeft()}</b><button class="btn danger" id="submitExam">Submit</button></div><section class="exam-question"><span class="kicker">TOPIC ${q.source}</span><h2>${esc(q.title)}</h2><div class="source-frame">${image?`<img src="${esc(image)}" alt="Source page for exam question" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><pre hidden>${esc(questionSourceText(q))}</pre>`:`<pre>${esc(questionSourceText(q))}</pre>`}</div><div class="mcq-options" style="margin-top:15px">${choiceLetters(q).map(c=>`<button data-exam-answer="${c}" class="${ex.answers[q.id]===c?"correct":""}">${c}</button>`).join("")}</div></section><div class="exam-nav"><button class="btn ghost" id="examPrev" ${ex.index===0?"disabled":""}>← Previous</button><div>${ex.items.map((x,i)=>`<button class="tag" data-jump="${i}" style="${ex.answers[x.id]?"border-color:var(--cyan)":""}">${i+1}</button>`).join("")}</div><button class="btn primary" id="examNext">${ex.index===ex.items.length-1?"Review":"Next →"}</button></div></div>`;$$('[data-exam-answer]').forEach(b=>b.onclick=()=>{ex.answers[q.id]=b.dataset.examAnswer;renderExamStage()});$$('[data-jump]').forEach(b=>b.onclick=()=>{ex.index=+b.dataset.jump;renderExamStage()});$("#examPrev").onclick=()=>{ex.index--;renderExamStage()};$("#examNext").onclick=()=>{if(ex.index<ex.items.length-1)ex.index++;else ex.index=0;renderExamStage()};$("#submitExam").onclick=submitExam}
function submitExam(){if(!state.exam||state.exam.submitted)return;state.exam.submitted=true;clearInterval(state.timer);const score=state.exam.items.filter(q=>state.exam.answers[q.id]===q.answer).length;state.profile.xp=(state.profile.xp||0)+score*3;state.profile.activity.unshift({text:`Mock exam: ${score}/${state.exam.items.length}`,at:Date.now()});saveProfile();renderExamResults()}
function renderExamResults(){const ex=state.exam,score=ex.items.filter(q=>ex.answers[q.id]===q.answer).length,pct=Math.round(score/ex.items.length*100);$("#view").innerHTML=`<div class="exam-stage"><section class="score-hero"><span class="kicker">EXPEDITION REPORT</span><div><b>${pct}%</b></div><h1>${score} / ${ex.items.length} correct</h1><p>${pct>=80?"Strong command. Review the missed concepts, not just the letters.":pct>=60?"The route is taking shape. Use the explanations to repair the weakest trail.":"Return to the map and rebuild the physical stories before another timed run."}</p><button class="btn primary" id="newExam">New exam</button></section>${ex.items.map((q,i)=>{const choice=ex.answers[q.id],ok=choice===q.answer;return `<details class="coach-step"><summary style="color:${ok?'var(--green)':'var(--coral)'}">${i+1}. ${esc(q.title)} · ${choice||"blank"} → ${q.answer}</summary>${solutionHTML(q)}</details>`}).join("")}</div>`;$("#newExam").onclick=()=>{state.exam=null;renderExam()}}

function renderCheatsheet(){setCrumb("Field guide");const sets=[{u:8,cards:[['Coulomb & field','F = k|q₁q₂|/r²\nE = F/q = kQ/r²','Draw direction first. Add vectors by component.'],['Continuous charge','dq = λ dl = σ dA = ρ dV\nE = k∫(dq/r²) r̂','Choose one source coordinate and project before integrating.'],['Flux & Gauss','Φ = ∫E·dA\n∮E·dA = Qenc/ε₀','Use Gauss to find E only with enough symmetry.']]},{u:9,cards:[['Potential energy','U = kq₁q₂/r\nWfield = −ΔU','For systems, add each distinct pair once.'],['Potential','V = U/q = k∫dq/r\nΔV = −∫E·dr','V is scalar; E is vector.'],['Energy','Ki + qVi = Kf + qVf','At a turning point K = 0, not necessarily F = 0.']]},{u:10,cards:[['Conductor rules','Emetal = 0\nVconductor = constant\nEout = σ/ε₀','A cavity containing charge can have nonzero field.'],['Capacitance','C = Q/ΔV\nU = Q²/(2C) = ½CV²','State whether Q or V stays fixed.'],['Parallel plates','C = κε₀A/d\nE = V/d','Parallel: same V. Series: same |Q| in a simple uncharged chain.'],['Coaxial','E = Q/(2πε₀Lr)\nC = 2πε₀L/ln(b/a)','Integrate 1/r across the gap.']]}];$("#view").innerHTML=pageHead("PRINTABLE REFERENCE","The field guide","Equations are starting points. The notes beside them tell you when they are legal to use.",`<button class="btn ghost" onclick="print()">Print / save PDF</button>`)+`<div class="decision-tree"><span class="kicker">WHICH METHOD?</span><div class="decision-row"><span>Discrete point charges?</span><i>→</i><span>Coulomb law + vector superposition</span></div><div class="decision-row"><span>Continuous source with weak symmetry?</span><i>→</i><span>Write dq and integrate dE or dV</span></div><div class="decision-row"><span>Spherical, cylindrical, or planar symmetry?</span><i>→</i><span>Try Gauss; justify constant E and direction</span></div><div class="decision-row"><span>Asked for speed or turning point?</span><i>→</i><span>Use K + qV, after finding potential difference</span></div></div>${sets.map(set=>`<section class="cheat-unit" style="--unit:${unitMeta[set.u].color}"><h2>Unit ${set.u} · ${unitMeta[set.u].name}</h2><div class="cheat-grid">${set.cards.map(c=>`<article class="cheat-card"><h3>${c[0]}</h3><code>${c[1]}</code><p>${c[2]}</p></article>`).join("")}</div></section>`).join("")}<section class="cheat-unit" style="--unit:#f59e0b"><h2>Integration recipe</h2><div class="cheat-grid">${[['1 · Element','Pick dl, dA, or dV and write dq from density.'],['2 · Geometry','Write the source-to-point distance and direction.'],['3 · Contribution','Use dE = k dq/r² or dV = k dq/r.'],['4 · Projection','For vectors, keep the component that survives symmetry.'],['5 · Bounds','Integrate over the actual source, then check units and limits.']].map(x=>`<div class="cheat-card"><h3>${x[0]}</h3><p>${x[1]}</p></div>`).join("")}</div></section>`}

function renderSettings(){setCrumb("Profile & memory");const acts=state.profile.activity.slice(0,12);$("#view").innerHTML=pageHead("YOUR RECORD","Profile, memory & sync","Your profile records completed trails, answers, tags, XP, streak, and recent activity. Export before changing browsers.")+`<div class="settings-grid"><section class="settings-card"><h2>Local profile</h2><p>Signed in locally as <b>${esc(state.profile.name)}</b>. This account works without a server.</p><div class="input-row"><button class="btn primary" id="exportData">Export backup</button><label class="btn ghost" for="importData">Import backup</label><input id="importData" type="file" accept="application/json" hidden></div><button class="btn danger" id="switchProfile" style="margin-top:12px">Switch profile</button></section><section class="settings-card"><h2>Optional cloud account</h2><p>Configure Supabase to sync across devices. The public anon key is protected by the included row-level security policy.</p><div class="input-stack"><input id="cloudEmail" type="email" placeholder="Email"><input id="cloudPassword" type="password" placeholder="Password (6+ characters)"><div><button class="btn primary" id="cloudSignIn">Sign in</button> <button class="btn ghost" id="cloudSignUp">Create cloud account</button></div><small id="cloudStatus" class="micro">${cloudConfigured()?"Cloud configuration detected.":"Local mode · see README to enable cloud sync."}</small></div></section><section class="settings-card"><h2>Recorded activity</h2><div class="activity-list">${acts.length?acts.map(a=>`<div class="activity"><span>${esc(a.text)}</span><time>${new Date(a.at).toLocaleDateString()}</time></div>`).join(""):"<p>No activity yet. Your first trail will appear here.</p>"}</div></section><section class="settings-card"><h2>What the tutor remembers</h2><p>The built-in guide reads the open lesson or question, your saved tags, and current attempt. It does not send data anywhere. A private live-AI proxy can be added in <code>config.js</code>.</p><p><b>${Object.keys(state.profile.notes||{}).length}</b> saved notes · <b>${Object.values(state.profile.tags).flat().length}</b> tags · <b>${Object.keys(state.profile.attempts).length}</b> question attempts</p></section></div>`;$("#exportData").onclick=exportData;$("#importData").onchange=importData;$("#switchProfile").onclick=()=>{$("#app").hidden=true;$("#profileGate").hidden=false;setupProfiles()};$("#cloudSignIn").onclick=()=>cloudAuth(false);$("#cloudSignUp").onclick=()=>cloudAuth(true)}
function exportData(){const blob=new Blob([JSON.stringify(state.profile,null,2)],{type:"application/json"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=`flux-${state.profile.name.toLowerCase().replace(/\W+/g,"-")}-backup.json`;a.click();URL.revokeObjectURL(a.href)}
function importData(e){const file=e.target.files[0];if(!file)return;const r=new FileReader();r.onload=()=>{try{const p=JSON.parse(r.result);if(!p.name||!p.id)throw Error();state.profile=p;saveProfile("Imported profile backup");toast("Backup imported");renderSettings()}catch{toast("That file is not a Flux backup")}};r.readAsText(file)}
function renderSearch(){setCrumb("Search");const q=new URLSearchParams(location.hash.split("?")[1]||"").get("q")?.toLowerCase()||"",lessons=state.data.lessons.filter(l=>JSON.stringify(l).toLowerCase().includes(q)),questions=state.data.solutions.filter(x=>JSON.stringify(x).toLowerCase().includes(q)).slice(0,40);$("#view").innerHTML=pageHead("SEARCH",q?`Results for “${q}”`:"Search the expedition","Find lessons, concepts, equations, and supplied practice explanations.")+`<form id="searchForm" class="input-row"><input id="searchInput" value="${esc(q)}" placeholder="Try Gauss, integration, turning point…"><button class="btn primary">Search</button></form><div class="section-title"><h2>Lessons · ${lessons.length}</h2></div>${lessons.map(l=>`<a class="question-card" href="#lesson/${l.id}"><span class="qnum">${l.id}</span><span><b>${esc(l.title)}</b><small>${esc(l.goal)}</small></span></a>`).join("")}<div class="section-title"><h2>Question explanations · ${questions.length}${questions.length===40?"+":""}</h2></div>${questions.map(q=>`<div class="question-card" data-search-q="${q.id}"><span class="qnum">${q.number}</span><span><b>${q.source} · ${esc(q.title)}</b><small>${esc(q.steps[0])}</small></span></div>`).join("")}`;$("#searchForm").onsubmit=e=>{e.preventDefault();location.hash="#search?q="+encodeURIComponent($("#searchInput").value)};$$('[data-search-q]').forEach(b=>b.onclick=()=>{state.practice.id=b.dataset.searchQ;state.practice.unit="all";state.practice.source="all";location.hash="#practice"})}

function openTutor(){$("#tutor").hidden=false;const c=state.context;$("#tutorContext").textContent=c?`${c.type}: ${c.item.title}`:"General E&M guide";setTimeout(()=>$("#tutorInput").focus(),50)}
function offlineTutor(input){const c=state.context,text=input.toLowerCase();if(c?.type==="question"){const q=c.item;if(/answer|solution/.test(text))return `The answer is ${q.answer}.\n\n${q.steps.join("\n\n")}\n\nCommon trap: ${q.pitfall}`;if(/integr|calculus|sum/.test(text))return q.integration;if(/hint|start|stuck/.test(text))return `Start here: ${q.steps[0]}\n\nBefore continuing, tell me which quantity is a vector and what direction you expect.`;return `For ${q.title}, first identify the physical rule. ${q.steps[0]} If that step is unclear, ask “why does that step work?”`}
  if(c?.type==="lesson"){const l=c.item;if(/integr|calculus/.test(text)){const section=l.sections.find(s=>/integr|dq|tiny|sum/i.test(s.body+s.title));return section?`${section.title}: ${section.body}`:"Use the six decisions from Base Camp: choose a tiny source piece, write dq, form its contribution, project direction, integrate over the source, then check units and limits."}if(/simple|beginner|confus/.test(text))return `${l.title}, in plain language: ${l.sections[0].body}`;if(/hint|start/.test(text))return `Try to answer this without equations first: ${l.goal} What objects create the field or energy in this situation?`;return `You are on “${l.title}.” The core goal is: ${l.goal} Ask me about a named step or paste your attempt.`}
  if(/gauss/.test(text))return "Gauss’s law always gives total flux. It gives E easily only when symmetry makes E constant on the useful part of a closed surface. Ask: sphere, long cylinder, or infinite plane?";if(/integr/.test(text))return "Integration is an exact sum: choose a tiny charge dq, write what that one piece contributes, then add every piece with bounds that cover the source.";return "Tell me the topic and what you have tried. I can give one hint at a time, explain an equation, or check a physical direction before the algebra."}
async function tutorReply(input){const config=window.FLUX_CONFIG||{};if(config.aiProxyUrl){try{const res=await fetch(config.aiProxyUrl,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({message:input,context:state.context,profile:{tags:state.profile.tags,attempts:state.profile.attempts}})});if(!res.ok)throw Error();const data=await res.json();return data.answer||data.output||offlineTutor(input)}catch{return offlineTutor(input)+"\n\n(The live tutor proxy was unavailable, so I used the built-in guide.)"}}return offlineTutor(input)}
function setupTutor(){$("#tutorButton").onclick=openTutor;$("#closeTutor").onclick=()=>$("#tutor").hidden=true;$$('.quick-prompts button').forEach(b=>b.onclick=()=>{$("#tutorInput").value=b.textContent;$("#tutorForm").requestSubmit()});$("#tutorForm").onsubmit=async e=>{e.preventDefault();const input=$("#tutorInput").value.trim();if(!input)return;const messages=$("#tutorMessages");messages.insertAdjacentHTML("beforeend",`<div class="message user">${esc(input)}</div>`);$("#tutorInput").value="";messages.scrollTop=messages.scrollHeight;const reply=await tutorReply(input);messages.insertAdjacentHTML("beforeend",`<div class="message guide">${esc(reply)}</div>`);messages.scrollTop=messages.scrollHeight}}
function cloudConfigured(){const c=window.FLUX_CONFIG||{};return Boolean(c.supabaseUrl&&c.supabaseAnonKey)}
async function cloudAuth(signup){if(!cloudConfigured()){toast("Add Supabase settings in config.js first");return}const c=window.FLUX_CONFIG,email=$("#cloudEmail").value,password=$("#cloudPassword").value,endpoint=signup?"signup":"token?grant_type=password";try{const res=await fetch(`${c.supabaseUrl}/auth/v1/${endpoint}`,{method:"POST",headers:{"apikey":c.supabaseAnonKey,"Content-Type":"application/json"},body:JSON.stringify({email,password})}),data=await res.json();if(!res.ok)throw Error(data.msg||data.error_description||"Authentication failed");if(data.access_token){localStorage.setItem("flux-cloud-token",data.access_token);localStorage.setItem("flux-cloud-user",data.user?.id||"");$("#cloudStatus").textContent="Cloud account connected. Loading saved progress…";const loaded=await cloudLoad();if(!loaded)await cloudSave();$("#cloudStatus").textContent="Cloud account connected. Progress is synchronized."}else $("#cloudStatus").textContent="Check your email to confirm the account."}catch(e){$("#cloudStatus").textContent=e.message}}
async function cloudLoad(){if(!cloudConfigured())return false;const token=localStorage.getItem("flux-cloud-token"),uid=localStorage.getItem("flux-cloud-user");if(!token||!uid)return false;const c=window.FLUX_CONFIG;try{const res=await fetch(`${c.supabaseUrl}/rest/v1/flux_profiles?user_id=eq.${encodeURIComponent(uid)}&select=data`,{headers:{apikey:c.supabaseAnonKey,Authorization:`Bearer ${token}`}});if(!res.ok)return false;const rows=await res.json();if(!rows[0]?.data)return false;const remote=rows[0].data;remote.id=state.profile.id;state.profile=remote;saveProfile("Loaded cloud progress");renderSettings();return true}catch{return false}}
async function cloudSave(){if(!cloudConfigured())return;const token=localStorage.getItem("flux-cloud-token"),uid=localStorage.getItem("flux-cloud-user");if(!token||!uid)return;const c=window.FLUX_CONFIG;try{await fetch(`${c.supabaseUrl}/rest/v1/flux_profiles`,{method:"POST",headers:{apikey:c.supabaseAnonKey,Authorization:`Bearer ${token}`,"Content-Type":"application/json",Prefer:"resolution=merge-duplicates"},body:JSON.stringify({user_id:uid,data:state.profile,updated_at:new Date().toISOString()})})}catch{}}

async function boot(){try{const names=["lessons","solutions","sources","frqs","lecture-solutions"],values=await Promise.all(names.map(n=>fetch(`${n}.json`).then(r=>{if(!r.ok)throw Error(n);return r.json()})));state.data=Object.fromEntries(names.map((n,i)=>[n.replace("-",""),values[i]]));state.data.frqs=values[3];state.data.lecture=values[4];setupProfiles();setupTutor();window.addEventListener("hashchange",route);$("#menuButton").onclick=()=>$(".sidebar").classList.toggle("open");$("#searchButton").onclick=()=>{const q=prompt("Search lessons and explanations");if(q)location.hash="#search?q="+encodeURIComponent(q)};$("#profileButton").onclick=()=>location.hash="#settings";document.addEventListener("click",e=>{if(e.target.closest(".sidebar a")&&innerWidth<780)$(".sidebar").classList.remove("open")});if("serviceWorker" in navigator&&location.protocol.startsWith("http"))navigator.serviceWorker.register("sw.js").catch(()=>{})}catch(e){document.body.innerHTML=`<main style="max-width:700px;margin:10vh auto;padding:30px"><h1>Flux could not load its study data.</h1><p>Open the folder through GitHub Pages or a local web server. Opening index.html directly with a file:// URL blocks the JSON curriculum files.</p><pre>${esc(e.message)}</pre></main>`}}
boot();
